  CALL SGET_HOST_DATA_RDWR (Z_YDCPG_SL1_PD9_SI_P, YDCPG_SL1%PD9_SI%F_P)
  CALL SGET_HOST_DATA_RDWR (Z_YDCPG_SL1_T0_P, YDCPG_SL1%T0%F_P)
