        & (:, JBLK)-Z_YDCPG_SL1_V9_P (:, JLEV, JBLK)*Z_YDVARS_GEOMETRY_GECLO_P&
        & (:, JBLK)*Z_YDVARS_GEOMETRY_GEMU_P (:, JBLK)
