      CALL SGET_HOST_DATA_RDWR (Z_YDVARS_GEOMETRY_GEMU_P, YDVARS%GEOMETRY%GEMU%FT0)
      CALL SGET_HOST_DATA_RDWR (Z_YDVARS_GEOMETRY_GESLO_P, YDVARS%GEOMETRY%GESLO%FT0)
